const sections = $('HTTP Request').first().json.MediaContainer.Directory;
const musicSection = sections.find(s => s.type === 'artist');
const machineIdentifier = $('HTTP Request Identity').first().json.MediaContainer.machineIdentifier;

const store = $getWorkflowStaticData('global');
store.machineIdentifier = machineIdentifier;

return [{ json: { sectionId: musicSection.key } }];

const container = $input.first().json.MediaContainer;
const totalSize  = parseInt(container.totalSize);
const tracks     = container.Metadata || [];
const currentOffset = parseInt(container.offset) || 0;

const store = $getWorkflowStaticData('global');
if (!store.tracks) store.tracks = [];
if (!store.sectionId) store.sectionId = $('Set Offset').first().json.sectionId; // read from the node that actually has it

const normalized = tracks.map(t => ({
  ratingKey : t.ratingKey,
  title     : t.title || 'Unknown Title',
  artist    : t.grandparentTitle || t.originalTitle || 'Unknown Artist',
  album     : t.parentTitle || 'Unknown Album',
  genre     : Array.isArray(t.Genre) ? t.Genre.map(g => g.tag).join(', ') : (t.Genre?.tag || ''),
  mood      : Array.isArray(t.Mood) ? t.Mood.map(m => m.tag).join(', ') : '',
  year      : t.parentYear || t.year || null,
  duration  : t.duration || null,
}));

store.tracks.push(...normalized);

const nextOffset = currentOffset + 300;
const hasMore    = nextOffset < totalSize;

return [{ json: {
  sectionId      : store.sectionId,
  offset         : nextOffset,
  hasMore,
  totalSize,
  totalCollected : store.tracks.length,
}}];

// ── v1.4.1 Build Prompt node ────────────────────────────────────────────
const batch = $('Loop Over Items').all().map(item => item.json).slice(0, 20);

// ── Hard, deterministic genre rules (evaluated in JS, not left to the LLM) ──
// These catch the "Metal/Prog Rock in Chill & Unwind" and "Classical belongs
// on its own" failure modes by computing a hint BEFORE the prompt is built,
// instead of hoping the model applies the rule consistently across 20 tracks.

const HIGH_ENERGY_GENRES = /metal|hardcore|punk|prog(ressive)?\s*rock|thrash|speed\s*metal|drum\s*(&|and|n)\s*bass|dnb|dubstep|grindcore|hard\s*rock|industrial/i;

const CLASSICAL_GENRES = /classical|orchestra|orchestral|symphony|baroque|opera|chamber\s*music|concerto|philharmonic/i;

const SPOKEN_WORD_HINT = /podcast|audiobook|spoken\s*word|comedy|talk\s*radio|lecture|sermon/i;
// v1.4.1: removed the bare "part\s*\d+" match -- it was catching legitimate
// multi-part songs (e.g. "Since I Left You, Pt. 2", "Shine On..., Pts. 1-5")
// and misrouting them into Podcasts & Audiobooks. Kept only the stronger,
// less ambiguous spoken-word signals.
const SPOKEN_WORD_TITLE_HINT = /\b(episode\s*\d+|chapter\s*\d+|interview\s*with|ep\.?\s*\d+)\b/i;

function computeHint(track) {
  const genre = (track.genre || '').toString();
  const title = (track.title || '').toString();

  if (SPOKEN_WORD_HINT.test(genre) || SPOKEN_WORD_TITLE_HINT.test(title)) {
    return 'LIKELY_SPOKEN_WORD';
  }
  if (CLASSICAL_GENRES.test(genre)) {
    return 'CLASSICAL';
  }
  if (HIGH_ENERGY_GENRES.test(genre)) {
    return 'HIGH_ENERGY — NEVER Deep Focus, Classical Focus, or Chill & Unwind';
  }
  return null;
}

const trackList = batch.map((t, i) => {
  const hint = computeHint(t);
  const hintStr = hint ? ` | Hint: ${hint}` : '';
  return `${i + 1}. id:${t.ratingKey} | "${t.title}" by ${t.artist} | Genre: ${t.genre || 'unknown'} | Year: ${t.year || 'unknown'}${hintStr}`;
}).join('\n');

const expectedIds = batch.map(t => t.ratingKey).join(', ');

const prompt = `You are a music classifier. Classify each track below into exactly one playlist.

VALID CATEGORIES (use ONLY these exact strings):
- Deep Focus
- Classical Focus
- Morning Energy
- Late Night Drive
- Workout Power
- Chill & Unwind
- Nostalgia Trip
- Party Mode
- Discover Gems
- Podcasts & Audiobooks
- SKIP_NON_MUSIC

CRITICAL DEFINITIONS & RULES (apply in this order):

0. GENRE HINTS ARE HARD CONSTRAINTS, NOT SUGGESTIONS.
   If a track has "Hint: HIGH_ENERGY" — it is FORBIDDEN to assign it to
   Deep Focus, Classical Focus, or Chill & Unwind, no matter what the title
   or artist suggests. Route it instead to Workout Power, Party Mode,
   Late Night Drive, or Discover Gems, whichever fits best.

1. "Classical Focus": Use this ONLY when Hint says "CLASSICAL", or the
   Genre field explicitly contains a classical-adjacent term (orchestral,
   symphony, opera, chamber music, baroque, concerto). Do NOT use this
   category based on "vibe" alone — a quiet, piano-led, or instrumental
   track is NOT classical just because it sounds mellow. Jazz standards
   (e.g. "Take Five"), singer-songwriter piano ballads (e.g. "Your Song"),
   and acoustic pop belong in Chill & Unwind or Deep Focus instead, even
   with no genre data. If in doubt and there is no CLASSICAL hint or
   explicit classical genre, do NOT choose Classical Focus.

2. "Deep Focus": Calm, low-energy, non-classical music suited for
   concentration (ambient, instrumental, downtempo, lo-fi, soft
   electronic). Never assign High-Energy-hinted tracks here.

3. "Chill & Unwind": Relaxed, mellow, low-tempo music for winding down.
   Never assign High-Energy-hinted tracks here.

4. "Podcasts & Audiobooks": Use this for any spoken-word audio — podcasts,
   audiobooks, interviews, lectures, comedy routines, news broadcasts.
   If Hint says "LIKELY_SPOKEN_WORD", strongly prefer this category over
   SKIP_NON_MUSIC — spoken word content should get its own playlist, not
   be discarded.

5. "SKIP_NON_MUSIC": Use this ONLY for audio that is neither music nor
   identifiable spoken-word content — e.g. sound effects, jingles,
   silence, corrupted/garbage metadata with no usable signal at all.

6. "Discover Gems": Actual music tracks that are eclectic, indie, obscure,
   or genuinely don't fit any specific mood category above. Must be music.

7. For all other categories (Morning Energy, Late Night Drive, Workout
   Power, Nostalgia Trip, Party Mode), classify by mood/energy/era as
   normal, respecting the High-Energy hint where relevant (e.g.
   High-Energy tracks are good candidates for Workout Power or Party Mode).

8. If genre is missing/unknown and there is no Hint, infer from title and
   artist naming conventions as a last resort. If nothing is inferable,
   prefer "Discover Gems" over guessing a mood you can't support.

9. Bracketed or parenthetical suffixes like [Radio Edit], [Live],
   [Original Mix], [Extended Mix], [Bonus Track], [Deluxe Edition],
   (Remastered), (Acoustic Version) are formatting/release-metadata tags,
   not content signals. Ignore them entirely when judging genre, mood, or
   whether something is spoken word — they do not indicate a podcast,
   interview, or broadcast.

TRACKS:
${trackList}

You MUST output an entry for every one of these ${batch.length} track IDs, with no exceptions: ${expectedIds}
Do not stop until all ${batch.length} tracks have an entry.

OUTPUT RULES:
- Return ONLY a JSON array
- Each element must be: {"id":"<the id number>","playlist":"<category name>"}
- Do NOT group by playlist
- Do NOT return track titles
- One object per track
- No explanation, no markdown

EXAMPLE OUTPUT:
[{"id":"1193","playlist":"Chill & Unwind"},{"id":"1194","playlist":"Classical Focus"}]

YOUR OUTPUT:`;

return [{
  json: {
    skip: false,
    ollamaBody: {
      //model: "qwen2.5:7b",
      //model: "mistral:7b",
      model: "gemma2:9b",
      //model: "llama3.2:1b",
      prompt,
      stream: false,
      keep_alive: "30m",
      options: { temperature: 0.1, num_predict: 900, num_ctx: 2048 }
    }
  }
}];

const store = $getWorkflowStaticData('global');
// Increased STALE_MS to 30 hours to safely accommodate Gemma 2 9B's ~24h run time
const STALE_MS = 30 * 60 * 60 * 1000;
const lockAge = store.runStartedAt ? Date.now() - store.runStartedAt : Infinity;

if (store.runInProgress && lockAge < STALE_MS) {
  throw new Error(`Another PlexPlayLister run is already in progress (started ${Math.round(lockAge/60000)} min ago) — aborting to avoid clobbering shared state.`);
}

store.runInProgress = true;
store.runStartedAt = Date.now();
store.tracks = [];
store.classificationMap = {};
store.emptyParseBatches = 0;
store.doneReasons = {};
store.errorBatches = 0;
store.createdPlaylists = [];   // <-- missing reset, causes stale playlist keys to leak across runs

const sectionId = $input.first().json.sectionId;
return [{ json: { cleared: true, sectionId } }];

const store = $getWorkflowStaticData('global');
const allTracks = store.tracks || [];
const classificationMap = store.classificationMap || {};
const FALLBACK = 'Discover Gems';

if (allTracks.length === 0) {
  throw new Error('store.tracks is empty when Group by Playlist ran.');
}

let trueGaps = 0; // tracks with NO classificationMap entry at all
const playlistGroups = {};

for (const track of allTracks) {
  const key = String(track.ratingKey);
  const hasEntry = Object.prototype.hasOwnProperty.call(classificationMap, key);
  if (!hasEntry) trueGaps++;
  const playlist = classificationMap[key] || FALLBACK;
  // NEW: Drop the track entirely if the LLM flagged it as non-music!
  if (playlist === 'SKIP_NON_MUSIC') continue;
  if (!playlistGroups[playlist]) playlistGroups[playlist] = new Set();
  playlistGroups[playlist].add(track.ratingKey);
}

const result = Object.entries(playlistGroups)
  .map(([name, keySet]) => ({
    json: { playlist: name, count: keySet.size, ratingKeys: Array.from(keySet) }
  }))
  .sort((a, b) => b.json.count - a.json.count);

result.push({ json: { playlist: '__DIAGNOSTIC__', trueGaps, totalTracks: allTracks.length, gapPercent: Math.round((trueGaps / allTracks.length) * 100) } });

result.push({ json: {
  playlist: '__DIAGNOSTIC__',
  trueGaps,
  totalTracks: allTracks.length,
  gapPercent: Math.round((trueGaps / allTracks.length) * 100),
  errorBatches: store.errorBatches || 0,
  emptyParseBatches: store.emptyParseBatches || 0,
  totalBatches: 1239
}});

return result;

const store = $getWorkflowStaticData('global');
const tracks = store.tracks || [];
if (tracks.length === 0) {
  throw new Error('No tracks in store. Check pagination loop.');
}

// Shuffle before batching. Plex returns tracks grouped by album/artist,
// so sequential batches of 13 were often entirely one album -- causing
// the LLM to anchor on the first track's classification and repeat it
// down the whole batch. A shuffled order breaks that pattern.
function shuffle(arr) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

return shuffle(tracks).map(t => ({ json: t }));

if ($input.first().json.skip === true) {
  return [{ json: { accepted: 0, rejected: 0, skipped: true } }];
}

const response = $input.first().json.response || '';
const cleaned = response
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

let classifications = [];
let recovered = false;

try {
  const parsed = JSON.parse(cleaned);
  if (Array.isArray(parsed)) {
    classifications = parsed;
  } else if (typeof parsed === 'object' && parsed !== null) {
    classifications = Object.values(parsed)
      .map(v => (typeof v === 'object' ? v : null))
      .filter(Boolean);
  }
} catch (e) {
  recovered = true;
  const pairRegex = /"id"\s*:\s*"?(\d+)"?[^}]*?"playlist"\s*:\s*"([^"]+)"/g;
  let match;
  while ((match = pairRegex.exec(cleaned)) !== null) {
    classifications.push({ id: match[1], playlist: match[2] });
  }
}

// v1.4: added "Classical Focus" and "Podcasts & Audiobooks" to match the
// updated Build Prompt categories. This list MUST stay in sync with the
// VALID CATEGORIES block in the Build Prompt node, or new categories will
// silently get rejected and dumped into Discover Gems with no error.
const VALID = new Set([
  "Deep Focus", "Classical Focus", "Morning Energy", "Late Night Drive",
  "Workout Power", "Chill & Unwind", "Nostalgia Trip", "Discover Gems",
  "Party Mode", "Podcasts & Audiobooks", "SKIP_NON_MUSIC"
]);

const store = $getWorkflowStaticData('global');   // ← declared ONCE, here
if (!store.classificationMap) store.classificationMap = {};

if (classifications.length === 0) {
  store.emptyParseBatches = (store.emptyParseBatches || 0) + 1;
}

let accepted = 0, rejected = 0;
for (const item of classifications) {
  const id = String(item.id || '');
  const playlist = item.playlist || '';
  if (id && VALID.has(playlist)) {
    store.classificationMap[id] = playlist;
    accepted++;
  } else if (id) {
    store.classificationMap[id] = 'Discover Gems';
    rejected++;
  }
}

const total = Object.keys(store.classificationMap).length;
return [{ json: { accepted, rejected, totalClassified: total, recovered } }];

const store = $getWorkflowStaticData('global');
store.errorBatches = (store.errorBatches || 0) + 1;
return [{ json: { accepted: 0, rejected: 0, error: true } }];

const targetTitle = $('Loop Over Items1').first().json.playlist;
const container = $input.first().json.MediaContainer;
const existing = (container.Metadata || []).find(p => p.title === targetTitle);

return [{ json: {
  playlist: targetTitle,
  ratingKeys: $('Loop Over Items1').first().json.ratingKeys,
  existingPlaylistKey: existing ? existing.ratingKey : null,
  machineIdentifier: $getWorkflowStaticData('global').machineIdentifier
}}];

// Replace the code in 'Create Playlist' with:
const matchNode = $('Find Match').first().json;

const ratingKeys = matchNode.ratingKeys || [];
const first50 = ratingKeys.slice(0, 50);
const remaining = ratingKeys.slice(50);
const uri = `server://${matchNode.machineIdentifier}/com.plexapp.plugins.library/library/metadata/${first50.join(',')}`;

return [{ json: {
  playlist: matchNode.playlist,
  createUri: uri,
  remaining,
  machineIdentifier: matchNode.machineIdentifier
}}];

const data = $('Create Playlist').first().json;
const container = $input.first().json?.MediaContainer;
const metadata = container?.Metadata?.[0] || container?.Directory?.[0];

if (!metadata?.ratingKey) {
  throw new Error(`Failed to extract ratingKey for created playlist "${data.playlist}"`);
}

// Store the created playlist info in global memory so the final chunker can use it
const store = $getWorkflowStaticData('global');
if (!store.createdPlaylists) store.createdPlaylists = [];

store.createdPlaylists.push({
  playlist: data.playlist,
  newPlaylistKey: metadata.ratingKey,
  remaining: data.remaining,
  machineIdentifier: data.machineIdentifier
});

return [{ json: {
  playlist: data.playlist,
  newPlaylistKey: metadata.ratingKey,
  remaining: data.remaining,
  machineIdentifier: data.machineIdentifier
}}];

const store = $getWorkflowStaticData('global');
const allPlaylists = store.createdPlaylists || [];
const allAppendJobs = [];

for (const data of allPlaylists) {
  // Only process if there are tracks remaining after the initial 50
  if (data.remaining && data.remaining.length > 0) {
    for (let i = 0; i < data.remaining.length; i += 50) {
      const chunk = data.remaining.slice(i, i + 50);

      allAppendJobs.push({
        json: {
          playlist: data.playlist,
          newPlaylistKey: data.newPlaylistKey,
          machineIdentifier: data.machineIdentifier,
          chunk: chunk
        }
      });
    }
  }
}

// Returns a flat list of every single append HTTP request needed across all 8 playlists!
return allAppendJobs;
